pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(address adr, bytes calldata data, uint256 value) public {
        vm.assume(adr != address(c));
        vm.assume(value <= address(c).balance);
        address owner = c.Owner();
        vm.deal(owner, value);
        vm.prank(owner);
        bool ok;
        try c.Command{value: value}(adr, data) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
